/**
 * The section titles of the README banners as outlines, one entry per word, so the build needs no font at run time.
 *
 * Same font and method as github-wordmark.mjs: Adwaita Sans ExtraBold (wght 800, opsz 14; SIL Open Font License 1.1, GNOME adwaita-fonts),
 * each word shaped with HarfBuzz on its own, drawn y-down with the baseline at y = 0 and the pen at x = 0, in font units (2048 per em).
 * A line of a title is its words at their advances with the space advance between them, so a line is not kerned across a space.
 *
 * Made with this script (fontTools and HarfBuzz's hb-shape). Save it as a file and run
 *   python3 SCRIPT ~/.local/share/fonts/adwaita-sans-fonts/AdwaitaSans-Regular.ttf Features and Project Philosophy Installation Getting Started Contributing Credits Community Support
 * and take "advance", "bounds" and "d" of each word from its output:
 *

 *   import json, subprocess, sys
 *   from fontTools.ttLib import TTFont
 *   from fontTools.varLib.instancer import instantiateVariableFont
 *   from fontTools.pens.svgPathPen import SVGPathPen
 *   from fontTools.pens.transformPen import TransformPen
 *   from fontTools.pens.boundsPen import BoundsPen
 *
 *   FONT, WORDS = sys.argv[1], sys.argv[2:]
 *   font = instantiateVariableFont(TTFont(FONT), {'wght': 800, 'opsz': 14})
 *   glyphs = font.getGlyphSet()
 *   out = {'upem': font['head'].unitsPerEm, 'words': {}}
 *   for word in [' '] + WORDS:
 *       shaped = json.loads(subprocess.check_output(['hb-shape', f'--font-file={FONT}', '--variations=wght=800,opsz=14', '--output-format=json', word]))
 *       pen = SVGPathPen(glyphs, ntos=lambda v: str(int(v)) if v == int(v) else ('%.1f' % v))
 *       bounds = BoundsPen(glyphs)
 *       x = 0
 *       for g in shaped:
 *           for p in (pen, bounds):
 *               glyphs[g['g']].draw(TransformPen(p, (1, 0, 0, -1, x + g['dx'], -g['dy'])))
 *           x += g['ax']
 *       out['words'][word] = {'advance': x, 'bounds': bounds.bounds, 'd': pen.getCommands()}
 *   print(json.dumps(out))
 *
 * `test/github-titles.test.mjs` pins the words and a hash of their outlines.
 */
/** The titles that a banner may draw, in the words of the maintainer. A banner draws one of these and no other text. */
export const TITLES = Object.freeze({
    features: 'Features and Project Philosophy',
    install: 'Installation and Getting Started',
    contributing: 'Contributing',
    credits: 'Credits',
    community: 'Community and Support',
});
export const TITLE_UNITS_PER_EM = 2048;
/** The distance from one baseline to the next, as a share of the font size. */
export const TITLE_LINE_HEIGHT = 1.15;

